insert into public.ce_course2_resources(id,data) values
('course2_module10_pdf','{"base64": "", "sha256": "983bc7dbc3c0517be41413f49509a0ddd6e4b38a4cb21fb73747e830add51952", "filename": "CE_HALO_Course2_Module10_MH_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course2_module10_questions','[{"module_id": "course_2_module_10", "question_id": "course_2_module_10_q01", "question_number": 1, "stem": "Which of the following anesthetic agents is a recognized trigger of malignant hyperthermia? ]", "choice_a": "Sevoflurane", "choice_b": "Propofol", "choice_c": "Dexmedetomidine", "choice_d": "Ketamine", "correct_choice": "a", "rationale": "Every potent volatile inhalational anesthetic (sevoflurane, desflurane, isoflurane, halothane, enflurane, methoxyflurane) is an MH trigger. Propofol, ketamine, and dexmedetomidine are all non-triggering (MH-safe) intravenous agents (MHAUS, 2024a; Rosenberg et al., 2020). [Pharm]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q02", "question_number": 2, "stem": "A patient with a documented family history of MH requires general anesthesia for open cholecystectomy. Which neuromuscular blocking agent is absolutely contraindicated? ]", "choice_a": "Cisatracurium", "choice_b": "Succinylcholine", "choice_c": "Vecuronium", "choice_d": "Rocuronium", "correct_choice": "b", "rationale": "Succinylcholine is a depolarizing neuromuscular blocker and an independent MH trigger. It is absolutely contraindicated in known or suspected MH-susceptible patients. Nondepolarizing agents (rocuronium, vecuronium, cisatracurium) are non-triggering and are the appropriate choice (Rosenberg et al., 2020; MHAUS, 2024b). [Pharm]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q03", "question_number": 3, "stem": "Which of the following combinations is a validated non-triggering (MH-safe) general anesthetic plan for an MH-susceptible adult? ]", "choice_a": "Sevoflurane + rocuronium + fentanyl", "choice_b": "Desflurane + succinylcholine + midazolam", "choice_c": "Propofol infusion + fentanyl + rocuronium, reversed with sugammadex", "choice_d": "Isoflurane + cisatracurium + morphine", "correct_choice": "c", "rationale": "A total intravenous anesthesia plan of propofol plus opioid plus a nondepolarizing NMBA is a standard, validated non-triggering approach. Reversal with sugammadex or neostigmine/glycopyrrolate is appropriate. All the other options include a volatile agent or succinylcholine (MHAUS, 2024b; AANA, 2024). [Pharm]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q04", "question_number": 4, "stem": "Which statement about nitrous oxide and regional anesthesia in the MH-susceptible patient is correct? ]", "choice_a": "Nitrous oxide is a mild MH trigger and should be avoided.", "choice_b": "Regional anesthesia is contraindicated in MH-susceptible patients.", "choice_c": "Ester local anesthetics trigger MH; amide local anesthetics are safe.", "choice_d": "Nitrous oxide and all amide and ester local anesthetics are non-triggering and are safe for MH-susceptible patients.", "correct_choice": "d", "rationale": "Nitrous oxide is non-triggering. All amide (lidocaine, bupivacaine, ropivacaine, mepivacaine) and ester (chloroprocaine, tetracaine) local anesthetics are non-triggering and safe. Regional and neuraxial techniques are often the preferred approach when the procedure permits (MHAUS, 2024b). [Pharm]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q05", "question_number": 5, "stem": "What is the earliest and most sensitive monitored sign of malignant hyperthermia in an anesthetized, mechanically ventilated patient? ]", "choice_a": "Progressive unexplained rise in end-tidal CO2 despite increased minute ventilation", "choice_b": "Dark cola-colored urine", "choice_c": "Rising core temperature", "choice_d": "Elevated creatine kinase", "correct_choice": "a", "rationale": "Progressive, unexplained rise in ETCO2 despite increased minute ventilation is the earliest and most sensitive monitored sign. Temperature rise, myoglobinuria, and CK elevation are all later findings. Waiting for temperature rise is a documented cause of delayed treatment (EMHG, 2024; MHAUS, 2024a). [Recognition]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q06", "question_number": 6, "stem": "Immediately after succinylcholine administration, a 6-year-old patient develops moderate masseter muscle rigidity that delays intubation. Which action is most appropriate? ]", "choice_a": "Ignore the finding and continue with sevoflurane maintenance.", "choice_b": "Recognize as a possible MH warning sign, continue with increased vigilance, discontinue any triggering agent, consider aborting or converting to a non-triggering plan, and be prepared to administer dantrolene if additional signs appear.", "choice_c": "Give an additional dose of succinylcholine to overcome the rigidity.", "choice_d": "Administer calcium channel blocker to relax the jaw.", "correct_choice": "b", "rationale": "Masseter muscle rigidity after succinylcholine identifies a subgroup at meaningfully higher MH risk. It should trigger immediate reassessment: discontinue any triggering agent, increase monitoring, and be prepared to give dantrolene if additional signs appear. Calcium channel blockers are contraindicated with dantrolene (Rosenberg et al., 2020; MHAUS, 2024a). [Recognition]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q07", "question_number": 7, "stem": "Which of the following findings, in a patient who has received a nondepolarizing neuromuscular blocker with a documented train-of-four count of zero, is nearly pathognomonic for malignant hyperthermia? ]", "choice_a": "Sinus tachycardia", "choice_b": "Hypotension", "choice_c": "Persistent generalized muscle rigidity", "choice_d": "Bronchospasm", "correct_choice": "c", "rationale": "Normal muscle should be flaccid under documented paralysis. Persistent generalized rigidity in a paralyzed patient is nearly pathognomonic for MH and should not be attributed to underdosing of the paralytic (Hopkins et al., 2025). [Recognition]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q08", "question_number": 8, "stem": "During a 45-minute sevoflurane anesthetic in a healthy adult, ETCO2 rises from 36 to 58 mmHg over 10 minutes despite an increase in minute ventilation, heart rate rises from 76 to 130, and the CRNA notes warm skin. Core temperature is 37.6°C. What is the most appropriate next action? ]", "choice_a": "Wait for core temperature to rise above 38.5°C before considering MH.", "choice_b": "Administer beta-blockade for the tachycardia.", "choice_c": "Deepen anesthesia by increasing sevoflurane concentration.", "choice_d": "Announce suspected MH, discontinue sevoflurane, hyperventilate with 100% O2, call for help and the MH cart, call the MHAUS hotline, and administer dantrolene 2.5 mg/kg IV.", "correct_choice": "d", "rationale": "ETCO2 rise is the earliest sign; temperature is often a late finding. Waiting for temperature to climb before initiating the MH pathway is a documented cause of delayed treatment and increased morbidity. Discontinue triggers, hyperventilate, activate the hotline, and give dantrolene immediately (Larach et al., 2019; EMHG, 2024). [Recognition]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q09", "question_number": 9, "stem": "What is the MHAUS 24-hour hotline number for expert MH consultation in the United States and Canada? ]", "choice_a": "1-800-644-9737", "choice_b": "1-800-222-1222", "choice_c": "1-800-848-6465", "choice_d": "1-800-424-9300", "correct_choice": "a", "rationale": "The MHAUS 24-hour hotline is 1-800-644-9737 in the United States and Canada, and +1-315-464-7079 internationally. It should be activated as early as a runner is available and the consultation should be documented (MHAUS, 2024a). [Protocol]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q10", "question_number": 10, "stem": "Which of the following actions should occur FIRST when MH is suspected during a sevoflurane anesthetic? ]", "choice_a": "Change the anesthesia circuit and CO2 absorbent.", "choice_b": "Call for help, discontinue the volatile anesthetic and any planned succinylcholine, hyperventilate with 100% O2, and prepare dantrolene.", "choice_c": "Insert an arterial line.", "choice_d": "Send laboratory studies and wait for results.", "correct_choice": "b", "rationale": "Calling for help, discontinuing the trigger, hyperventilating with 100 percent oxygen, and preparing dantrolene are the immediate simultaneous first actions. Changing the circuit and inserting lines are important but secondary and must not delay dantrolene (MHAUS, 2024a; EMHG, 2024). [Protocol]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q11", "question_number": 11, "stem": "What fresh gas flow and oxygen concentration are recommended during the acute MH response? ]", "choice_a": "Room air at 5 L/min", "choice_b": "100% O2 at 4 L/min with normal minute ventilation", "choice_c": "100% O2 at ≥ 10 L/min with hyperventilation at 2–3× normal minute ventilation", "choice_d": "50% O2 at 2 L/min", "correct_choice": "c", "rationale": "MHAUS and EMHG both recommend 100 percent oxygen at 10 L/min or more with minute ventilation increased to 2–3 times normal to eliminate the massive CO2 load produced by hypermetabolism (MHAUS, 2024a; EMHG, 2024). [Protocol]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q12", "question_number": 12, "stem": "During an MH crisis, when should the anesthesia circuit and CO2 absorbent be changed? ]", "choice_a": "It is not necessary if the vaporizer is turned off.", "choice_b": "Before administering dantrolene, because contamination will continue triggering.", "choice_c": "Only after transfer to the ICU.", "choice_d": "Once dantrolene is running and adequate personnel are available; do not delay dantrolene for this step. Consider activated charcoal filters.", "correct_choice": "d", "rationale": "Changing the circuit and absorbent is a supportive step to reduce ongoing volatile exposure but must not delay the first dantrolene dose. Activated charcoal filters (e.g., Vapor-Clean) rapidly reduce residual volatile concentration and are a useful adjunct (MHAUS, 2024a; MHAUS, 2024b). [Protocol]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q13", "question_number": 13, "stem": "Which of the following is the correct temperature target for stopping active cooling during MH treatment? ]", "choice_a": "Stop at 38.0°C to avoid iatrogenic hypothermia and overshoot", "choice_b": "Stop at 36.0°C", "choice_c": "Stop at 37.0°C", "choice_d": "Continue cooling until the patient reaches 35.0°C", "correct_choice": "a", "rationale": "Active cooling is stopped at core temperature 38.0°C to avoid overshoot and iatrogenic hypothermia. Cold IV saline (not lactated Ringer''s, which contains potassium), surface ice packs, and lavage may all be used until this target is reached (MHAUS, 2024a). [Protocol]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q14", "question_number": 14, "stem": "What is the correct initial IV bolus dose of dantrolene for the treatment of acute MH? ]", "choice_a": "5 mg/kg IV", "choice_b": "2.5 mg/kg IV", "choice_c": "10 mg/kg IV", "choice_d": "1 mg/kg IV", "correct_choice": "b", "rationale": "The initial dantrolene dose is 2.5 mg/kg IV push, repeated every 5 to 10 minutes until reversal of hypermetabolic signs. There is no fixed maximum dose (MHAUS, 2024a; Ryanodex prescribing information, 2023). [Dose]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q15", "question_number": 15, "stem": "Traditional dantrolene 20 mg vials require which of the following for reconstitution? ]", "choice_a": "5 mL of sterile water per vial, mixed in about 20 seconds.", "choice_b": "10 mL of 0.9% saline per vial.", "choice_c": "60 mL of sterile water per vial, requiring approximately 5 minutes of vigorous shaking per vial to fully dissolve.", "choice_d": "20 mL of dextrose 5% per vial.", "correct_choice": "c", "rationale": "Traditional dantrolene 20 mg vials each require 60 mL of sterile water for injection and approximately 5 minutes of vigorous shaking to dissolve. A 2.5 mg/kg bolus for a 70 kg adult (175 mg, ≈ 9 vials) requires about 540 mL of solution and multiple team members working in parallel (Ryanodex prescribing information, 2023; MHAUS, 2024a). [Dose]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q16", "question_number": 16, "stem": "Ryanodex is supplied as a single 250 mg vial. Approximately how much sterile water is required for reconstitution, and how long does reconstitution take? ]", "choice_a": "60 mL of sterile water; approximately 5 minutes", "choice_b": "20 mL of sterile water; approximately 2 minutes", "choice_c": "100 mL of sterile water; approximately 10 minutes", "choice_d": "5 mL of sterile water; less than 20 seconds", "correct_choice": "d", "rationale": "Ryanodex 250 mg is reconstituted in 5 mL of sterile water for injection and forms a suspension in under 20 seconds. This dramatically shortens time to first dose compared with traditional dantrolene (Ryanodex prescribing information, 2023). [Dose]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q17", "question_number": 17, "stem": "For an 80-kg adult with active MH, approximately how many vials of traditional dantrolene (20 mg per vial) are required for a single 2.5 mg/kg bolus? ]", "choice_a": "10 vials", "choice_b": "2 vials", "choice_c": "5 vials", "choice_d": "20 vials", "correct_choice": "a", "rationale": "2.5 mg/kg × 80 kg = 200 mg. At 20 mg per vial of traditional dantrolene, 200 mg ÷ 20 mg = 10 vials per bolus. This illustrates the logistic burden of traditional dantrolene and why Ryanodex (1 vial = 250 mg) is often preferred (MHAUS, 2024a). [Dose]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q18", "question_number": 18, "stem": "After successful reversal of an MH crisis in a 70-kg adult, what is the recommended post-crisis dantrolene regimen to prevent recrudescence? ]", "choice_a": "Dantrolene 5 mg/kg PO every 12 hours for 7 days.", "choice_b": "Dantrolene 1 mg/kg IV every 4–6 hours (approximately 70 mg every 4–6 hours) or 0.25 mg/kg/hr infusion, continued for at least 24 hours.", "choice_c": "No further dantrolene is required after the acute crisis resolves.", "choice_d": "Dantrolene 10 mg/kg IV bolus once daily for 3 days.", "correct_choice": "b", "rationale": "Post-crisis maintenance is dantrolene 1 mg/kg IV every 4–6 hours (or an infusion of approximately 0.25 mg/kg/hr) for at least 24 hours, with extension to 48 hours in severe cases. This prevents the 20–25 percent recrudescence rate documented in registry data (MHAUS, 2024a; Litman et al., 2018). [Dose]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q19", "question_number": 19, "stem": "A patient in an MH crisis develops potassium 6.4 mEq/L with peaked T waves. Which of the following is the correct combination of therapies? ]", "choice_a": "Verapamil IV to slow the ventricular response and shift potassium.", "choice_b": "Potassium chloride replacement.", "choice_c": "Calcium chloride for membrane stabilization, regular insulin with dextrose for intracellular shift, sodium bicarbonate, and hyperventilation.", "choice_d": "Diltiazem infusion combined with dantrolene.", "correct_choice": "c", "rationale": "Standard hyperkalemia management applies: membrane stabilization (calcium chloride or gluconate), intracellular shift (insulin plus dextrose, hyperventilation, sodium bicarbonate), and — when able — enhanced elimination. Calcium channel blockers must not be used with dantrolene because of reported severe hyperkalemia and cardiovascular collapse (MHAUS, 2024a). [Adjunctive]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q20", "question_number": 20, "stem": "Which of the following IV fluids should be avoided during MH volume resuscitation? ]", "choice_a": "Normal saline (0.9% NaCl)", "choice_b": "Cold normal saline", "choice_c": "Plasmalyte", "choice_d": "Lactated Ringer''s solution", "correct_choice": "d", "rationale": "Lactated Ringer''s contains potassium and should be avoided during MH because hyperkalemia is a leading cause of MH-related cardiac arrest. Normal saline, plasmalyte, and cold normal saline are appropriate (MHAUS, 2024a). [Adjunctive]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q21", "question_number": 21, "stem": "Why are calcium channel blockers (verapamil, diltiazem) contraindicated during MH treatment? ]", "choice_a": "In combination with dantrolene they have been associated with severe hyperkalemia and cardiovascular collapse.", "choice_b": "They cause muscle weakness that delays extubation.", "choice_c": "They are ineffective at controlling ventricular dysrhythmias.", "choice_d": "They increase intracellular calcium and worsen MH.", "correct_choice": "a", "rationale": "Verapamil and diltiazem in combination with dantrolene have been associated with severe hyperkalemia and cardiovascular collapse in animal and human reports; the combination is explicitly contraindicated. Amiodarone (or procainamide as alternative) is preferred for MH-related ventricular dysrhythmias (MHAUS, 2024a; Rosenberg et al., 2020). [Adjunctive]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q22", "question_number": 22, "stem": "What proportion of successfully treated MH patients experience recrudescence, and within what typical time frame? ]", "choice_a": "Recrudescence has not been documented in the modern era", "choice_b": "About 20–25%, typically within 6–36 hours of initial resolution", "choice_c": "About 1%, within the first hour", "choice_d": "About 50%, within 15 minutes", "correct_choice": "b", "rationale": "Recrudescence occurs in approximately 20–25 percent of survivors, typically within 6 to 36 hours of initial resolution. This is the fundamental reason for mandatory ICU monitoring for at least 24 hours and continued dantrolene (Litman et al., 2018; MHAUS, 2024a). [Post-crisis]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q23", "question_number": 23, "stem": "Following successful MH treatment, which of the following is appropriate management of the patient''s biologic family? ]", "choice_a": "No family evaluation is necessary; MH is not inherited.", "choice_b": "Only siblings of the same sex require evaluation.", "choice_c": "The patient and all biologic first-degree relatives should be referred to an MHAUS-designated MH testing center for genetic testing and/or caffeine–halothane contracture testing (CHCT/IVCT).", "choice_d": "Only pediatric relatives require evaluation.", "correct_choice": "c", "rationale": "MH is autosomal dominant, and first-degree relatives have approximately a 50 percent chance of susceptibility. The patient and all biologic first-degree relatives should be referred to an MHAUS-designated testing center for definitive evaluation by genetic testing and/or CHCT/IVCT (Rosenberg et al., 2020; Hopkins et al., 2021). [Post-crisis]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q24", "question_number": 24, "stem": "An MH-susceptible patient is scheduled for elective surgery. Which of the following describes an appropriate way to prepare the anesthesia machine? ]", "choice_a": "Flush the machine at 2 L/min for 5 minutes.", "choice_b": "The machine cannot be adequately prepared and should not be used.", "choice_c": "No preparation is required if a vaporizer has not been used in the last hour.", "choice_d": "Remove or disable the vaporizers, replace the circuit and CO2 absorbent, and flush the machine with 100% O2 at ≥ 10 L/min for the manufacturer-specified time; alternatively, place activated charcoal filters on the inspiratory and expiratory limbs, which reduces residual volatile to < 5 ppm in under 90 seconds.", "correct_choice": "d", "rationale": "Modern anesthesia workstations retain volatile anesthetic in plastic components and CO2 absorbent for hours. Two acceptable approaches exist: vaporizer removal plus circuit and absorbent replacement plus manufacturer-specified 100% O2 flush (typically 20–100 min), or use of activated charcoal filters (e.g., Vapor-Clean), which reduce residual volatile below 5 ppm within 90 seconds (MHAUS, 2024b). [Prevention]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q25", "question_number": 25, "stem": "What is the minimum dantrolene stocking requirement, per MHAUS, for any facility that administers volatile anesthetics or succinylcholine — including ambulatory surgery centers and office-based practices? ]", "choice_a": "36 vials of traditional dantrolene (720 mg) or 3 vials of Ryanodex (750 mg), plus corresponding sterile water for injection and mixing supplies.", "choice_b": "No minimum is required for ambulatory surgery centers.", "choice_c": "6 vials of traditional dantrolene or 1 vial of Ryanodex.", "choice_d": "12 vials of traditional dantrolene or 1 vial of Ryanodex.", "correct_choice": "a", "rationale": "MHAUS recommends a minimum of 36 vials of traditional dantrolene (720 mg) or 3 vials of Ryanodex (750 mg), plus sterile water and mixing supplies, at every facility that administers volatile anesthetics or succinylcholine. The requirement applies equally to ambulatory surgery centers, office-based practices, endoscopy suites, dental facilities, and obstetric units (MHAUS, 2024b; AANA, 2024). [Prevention]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q26", "question_number": 26, "stem": "During an intraoperative MH crisis, the patient develops a serum potassium of 6.9 mEq/L with peaked T waves on ECG. In addition to hyperventilation and dantrolene, which combination of treatments is MOST appropriate? ]", "choice_a": "Kayexalate 30 g PO and observation.", "choice_b": "Calcium chloride 10 mg/kg IV, regular insulin 10 units IV with 25 g dextrose, and sodium bicarbonate for documented acidosis.", "choice_c": "Verapamil 5 mg IV and furosemide 40 mg IV.", "choice_d": "Sodium bicarbonate alone; other agents are contraindicated in MH.", "correct_choice": "b", "rationale": "Hyperkalemia in MH is life-threatening and drives dysrhythmias. First-line treatment is membrane stabilization with calcium chloride (10 mg/kg) or calcium gluconate, intracellular potassium shift with regular insulin (10 units IV) plus dextrose (25 g), and correction of metabolic acidosis with sodium bicarbonate. Calcium channel blockers such as verapamil are CONTRAINDICATED in MH because they can cause profound hyperkalemia and cardiac arrest when combined with dantrolene (MHAUS, 2024a; AANA, 2024). [Adjunct]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q27", "question_number": 27, "stem": "An MH-susceptible patient with a family history of a confirmed RYR1 pathogenic variant requires a laparoscopic cholecystectomy at an ambulatory surgery center. Which anesthetic plan is MOST appropriate? ]", "choice_a": "Regional anesthesia only; general anesthesia is absolutely contraindicated in MH-susceptible patients.", "choice_b": "Sevoflurane with rocuronium reversed by sugammadex; the reversal agent eliminates MH risk.", "choice_c": "Non-triggering total intravenous anesthesia (TIVA) with propofol and remifentanil, a flushed anesthesia machine or new circuit, activated charcoal filters, standard PACU monitoring for at least 1 hour, and confirmed dantrolene stock (36 vials traditional or 3 vials Ryanodex) on site.", "choice_d": "Cancel the case; MH-susceptible patients cannot be safely anesthetized at an ambulatory surgery center.", "correct_choice": "c", "rationale": "MH-susceptible patients can be safely anesthetized at ambulatory surgery centers when the facility meets MHAUS stocking requirements and the plan uses non-triggering technique. TIVA with propofol and an opioid (or regional anesthesia) is standard. The anesthesia machine must be prepared per manufacturer instructions or bypassed with a charcoal filter (e.g., Vapor-Clean). Sugammadex does not neutralize volatile agents. General anesthesia is not contraindicated when non-triggering agents are used (MHAUS, 2024b; EMHG, 2024; AANA, 2024). [Prevention]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q28", "question_number": 28, "stem": "Following successful treatment of an intraoperative MH crisis, what is the recommended MINIMUM duration of post-crisis dantrolene therapy and level of monitoring? ]", "choice_a": "Oral dantrolene 100 mg twice daily for 3 days on the surgical ward.", "choice_b": "Single bolus is sufficient; discharge from PACU when awake.", "choice_c": "Dantrolene infusion for 4 hours followed by discharge home.", "choice_d": "Dantrolene 1 mg/kg IV every 6 hours for at least 24 hours, with continuous ICU monitoring for at least 24-48 hours for recrudescence, hyperkalemia, dysrhythmias, myoglobinuria, acute kidney injury, disseminated intravascular coagulation, and compartment syndrome.", "correct_choice": "d", "rationale": "Per MHAUS, after control of an acute MH episode, dantrolene 1 mg/kg IV should continue every 6 hours for at least 24 hours, and the patient should be monitored in an ICU for a minimum of 24-48 hours. Recrudescence occurs in approximately 20% of cases, most commonly within the first 24 hours. Continued surveillance for hyperkalemia, dysrhythmias, myoglobinuria, acute kidney injury, DIC, and compartment syndrome is essential (MHAUS, 2024a; EMHG, 2024). [Post-Crisis]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q29", "question_number": 29, "stem": "Which finding is considered the EARLIEST and MOST sensitive monitored sign of an intraoperative MH crisis? ]", "choice_a": "Unexplained, progressive rise in end-tidal carbon dioxide (EtCO2) that does not respond to increased minute ventilation.", "choice_b": "Sudden dark or cola-colored urine.", "choice_c": "Core temperature >39°C.", "choice_d": "Sinus bradycardia with hypotension.", "correct_choice": "a", "rationale": "An unexplained, progressive rise in EtCO2 that does not respond to increased minute ventilation is widely recognized as the earliest and most sensitive monitored sign of MH. Hyperthermia is a late sign and often lags the metabolic derangement by 30-60 minutes. Sinus tachycardia (not bradycardia) is a common early cardiovascular finding. Cola-colored urine reflects myoglobinuria and appears late (MHAUS, 2024a; EMHG, 2024). [Recognition]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q30", "question_number": 30, "stem": "After stabilizing a patient from an MH crisis, which referral is MOST important for the patient and biologic family members? ]", "choice_a": "Refer the patient to an endocrinologist for thyroid work-up.", "choice_b": "Refer the patient and first-degree biologic relatives to an MHAUS-recognized MH Testing Center for caffeine-halothane contracture testing (CHCT) and/or targeted genetic testing (RYR1, CACNA1S, STAC3).", "choice_c": "Recommend that family members simply inform their anesthesia providers of the family history at the time of future surgery; no formal testing is required.", "choice_d": "Refer only the patient for genetic testing; family testing is not recommended.", "correct_choice": "b", "rationale": "The patient and all first-degree biologic relatives (parents, siblings, children) should be referred to an MHAUS-recognized MH Testing Center. The gold-standard diagnostic test is the caffeine-halothane contracture test (CHCT) on a fresh muscle biopsy. Targeted genetic testing for RYR1, CACNA1S, and STAC3 variants is also available and may be used as a screening tool. Family members should not rely solely on verbal history; formal testing informs safe future anesthetic planning (MHAUS, 2024a; EMHG, 2024). [Post-Crisis]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_10", "question_id": "course_2_module_10_q31", "question_number": 31, "stem": "A CRNA is called to activate the MHAUS 24-hour MH Hotline during an acute crisis. What is the correct number, and what is its PRIMARY purpose? ]", "choice_a": "911; to request emergency medical services transport to a tertiary center.", "choice_b": "The manufacturer of dantrolene, to authorize additional vial release.", "choice_c": "1-800-644-9737 (US) or +001-315-464-7079 (outside US); real-time consultation with an on-call MH expert for management of the acute crisis and post-crisis care.", "choice_d": "The state Board of Nursing, to report the adverse event.", "correct_choice": "c", "rationale": "The MHAUS MH Hotline (1-800-MH-HYPER / 1-800-644-9737 in the US; +001-315-464-7079 outside the US) provides 24-hour real-time consultation with an on-call MH expert for management of active MH crises and post-crisis care. Activation of the hotline is a step in the MHAUS emergency response and should occur as early as feasible without delaying dantrolene administration or supportive care (MHAUS, 2024a; AANA, 2024). [Response]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
